"""Weekly timesheet lines built from a list of shifts."""

from typing import Dict, Iterable, List, Tuple
from hourglass.models import Shift

def _check(shifts: List[Shift]) -> None:
    if not shifts:
        raise ValueError("no shifts to build a timesheet from")
    if any(not shift.worker.strip() for shift in shifts):
        raise ValueError("a shift has a blank worker name")

def _tally(shifts: Iterable[Shift]) -> Dict[str, Tuple[int, int]]:
    totals = {}
    for shift in shifts:
        count, minutes = totals.get(shift.worker.strip(), (0, 0))
        totals[shift.worker.strip()] = (count + 1, minutes + shift.span.minutes)
    return totals

# ---
def timesheet_lines(shifts: Iterable[Shift]) -> List[str]:
    """One line per worker, like Brisa: 3 shifts, 12.5 hours. Busiest first."""
    shifts = list(shifts)
    _check(shifts)
    rows = sorted(_tally(shifts).items(), key=lambda r: (-r[1][1], -r[1][0], r[0]))
    return [f"{n}: {c} shifts, {m / 60:.1f} hours" for n, (c, m) in rows]

