# owner: platform
import unittest
from hourglass.timesheet import timesheet_lines
from hourglass.models import Shift, Span

def shift(worker, day, start, end):
    return Shift(worker, day, Span(start * 60, end * 60))

class TimesheetTests(unittest.TestCase):
    def test_one_line_per_worker_busiest_first(self):
        shifts = [
            shift("Ana", "mon", 9, 12),
            shift("Brisa", "mon", 9, 17),
            shift("Ana", "tue", 9, 11),
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            ["Brisa: 1 shifts, 8.0 hours", "Ana: 2 shifts, 5.0 hours"],
        )

    def test_hours_use_one_decimal(self):
        lines = timesheet_lines([Shift("Ana", "mon", Span(540, 620))])
        self.assertEqual(lines, ["Ana: 1 shifts, 1.3 hours"])

    def test_ties_break_by_name(self):
        shifts = [shift("Zed", "mon", 9, 10), shift("Amy", "mon", 9, 10)]
        self.assertEqual(
            [line.split(":")[0] for line in timesheet_lines(shifts)],
            ["Amy", "Zed"],
        )

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker_raises(self):
        for name in ("", "   "):
            with self.subTest(name=name):
                with self.assertRaises(ValueError):
                    timesheet_lines([shift(name, "mon", 9, 10)])
